    if section_id == 4:
        return _vector(tuple(content), _encode_table_type)
    if section_id == 5:
        return _vector(tuple(content), _encode_limits)
    if section_id == 6:
        return _vector(tuple(content), _encode_global)
    if section_id == 7:
        return _vector(tuple(content), _encode_export)
    if section_id == 8:
        return _u_leb(content)
    if section_id == 9:
        return _vector(tuple(content), _encode_element_segment)
    if section_id == 10:
        return _vector(tuple(content), _encode_body)
    if section_id == 11:
        return _vector(tuple(content), _encode_data_segment)
    if section_id == 12:
        return _u_leb(content)
    raise WasmStructuralError("cannot encode unknown WebAssembly section")


