def _u_leb(value: int) -> bytes:
    if type(value) is not int or value < 0:
        raise WasmStructuralError("unsigned LEB128 value is negative")
    encoded = bytearray()
    while True:
        byte = value & 0x7F
        value >>= 7
        if value:
            byte |= 0x80
        encoded.append(byte)
        if not value:
            return bytes(encoded)


def _s_leb(value: int, bits: int) -> bytes:
    if type(value) is not int or not -(1 << (bits - 1)) <= value < 1 << (bits - 1):
        raise WasmStructuralError("signed LEB128 value is out of range")
    encoded = bytearray()
    while True:
        byte = value & 0x7F
        value >>= 7
        done = (value == 0 and not byte & 0x40) or (value == -1 and byte & 0x40)
        encoded.append(byte if done else byte | 0x80)
        if done:
            return bytes(encoded)
